#![allow(clippy::expect_used, clippy::unwrap_used, clippy::panic)]
// SPDX-License-Identifier: Apache-2.0
//! T4's SQL item page against `vectors/item-page-sql.json`, generated by
//! `vectors/make-item-page-sql-vectors.ts` from a real Store: the schema and rows of the six
//! tables the page reads, and the pages `readBoundedItemPage` gave for a few budgets and
//! cursors — a finished message, a streaming one whose preview is its newest 4096 units (offset
//! marked), a reasoning item, a tool call and notices.
//!
//! Ports `ItemStore.wirePage`, `newestBefore`, `hasItemBefore`, `pageItem` and `ItemTextStore.read`
//! through the store's own schema, so the SQL, the size rule, the decoded previews and the
//! bounded page's shaping are all compared with the TypeScript's bytes.

use std::sync::Arc;

use ace_json::Value;
use ace_store::reads::item_page_sql::SqlItemPage;
use ace_store::reads::items::{PageError, bounded_item_page};
use ace_store::reads::stored::trusted_from;
use ace_store::{Connection, OpenOptions};

fn vectors() -> Value {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/vectors/item-page-sql.json");
    let text = std::fs::read_to_string(path).expect("read item-page-sql.json");
    ace_json::parse(&text).expect("parse item-page-sql.json")
}

fn array<'a>(value: &'a Value, key: &str) -> &'a [Value] {
    match value.get(key) {
        Some(Value::Array(items)) => items,
        _ => panic!("{key} is not an array"),
    }
}

fn text(value: &Value, key: &str) -> String {
    match value.get(key) {
        Some(Value::String(seen)) => seen.as_str().to_owned(),
        _ => panic!("{key} is not a string"),
    }
}

fn number(value: &Value, key: &str) -> f64 {
    match value.get(key) {
        Some(Value::Number(seen)) => seen.value(),
        _ => panic!("{key} is not a number"),
    }
}

fn strings(value: &Value, key: &str) -> Vec<String> {
    array(value, key)
        .iter()
        .map(|entry| match entry {
            Value::String(seen) => seen.as_str().to_owned(),
            _ => panic!("{key} holds a non-string"),
        })
        .collect()
}

/// The fixture's database, built in memory from its schema and rows.
fn database(vectors: &Value) -> Arc<Connection> {
    let conn = Connection::open(
        ":memory:",
        OpenOptions {
            read_only: false,
            timeout_ms: 0,
        },
    )
    .expect("open in-memory store");
    // The page's queries touch only these six tables; their foreign keys name the rest of the
    // home, which this fixture does not carry.
    conn.exec("PRAGMA foreign_keys = OFF")
        .expect("foreign keys off");
    for statement in strings(vectors, "schema") {
        conn.exec(&statement).expect("create schema");
    }
    for statement in strings(vectors, "inserts") {
        conn.exec(&statement).expect("insert fixture row");
    }
    conn
}

/// Every bounded page over the real schema is the TypeScript's bytes.
#[test]
fn every_sql_page_is_the_typescripts() {
    let vectors = vectors();
    let conn = database(&vectors);
    for case in array(&vectors, "cases") {
        let name = text(case, "name");
        let thread = text(case, "threadId");
        let source = SqlItemPage::new(conn.clone(), &thread, trusted_from(0));
        let page = bounded_item_page(
            &source,
            &thread,
            number(case, "before") as u64,
            number(case, "limit") as usize,
            number(case, "byteLimit") as usize,
        )
        .unwrap_or_else(|error| panic!("{name}: {error:?}"));
        assert_eq!(ace_json::to_string(&page), text(case, "expected"), "{name}");
    }
}

/// The store's own page reports capacity as the bounded page expects, and its newest/older
/// queries agree with the rows a page returned.
#[test]
fn the_store_page_answers_capacity_newest_and_older() {
    use ace_store::reads::items::ItemPageSource;

    let vectors = vectors();
    let conn = database(&vectors);
    let case = array(&vectors, "cases")
        .iter()
        .find(|case| text(case, "name").contains("too small"))
        .expect("a capacity case");
    let thread = text(case, "threadId");
    let source = SqlItemPage::new(conn.clone(), &thread, trusted_from(0));
    let before = number(case, "before") as u64;
    assert_eq!(
        source.page(before, 10, 600),
        Err(PageError::Capacity),
        "a page with no room reports capacity"
    );
    let (item, seq) = source.newest_before(before).expect("the newest item");
    assert_eq!(seq, 52);
    assert_eq!(
        item.get("id").and_then(|id| match id {
            Value::String(seen) => Some(seen.as_str()),
            _ => None,
        }),
        Some("m5")
    );
    assert!(
        source.has_item_before(52),
        "older rows exist before the newest"
    );
    assert!(!source.has_item_before(0), "nothing is older than the log");
}
